//! 📑️ Admitted Document styles, image octets and recursively bounded typed block trees.
use crate::standards::v1::subsets::document::schema::snapshot::{SemioDocumentSnapshot,DocStyle,DocImage,DocBlock,DocRun,RunStyle,DocListItem,DocTableRow,DocTableCell,STDIO_SEMIODOCUMENT_DOCUMENT_SCHEMA};
use crate::standards::v1::subsets::base::io::sqlite::snapshot::native_decoding as native;
use semio_framework_value::native_decoding::NativeDecodeControl;
use semio_framework_value::{ValueError,ValueRefusalKind};
use store::sqlite_snapshot::{SqliteSnapshotControl,SqliteDatabaseLimits};
pub(crate) fn decode(payload:&store::os_io::IoPayload,control:&mut SqliteSnapshotControl<'_>)->Result<SemioDocumentSnapshot,ValueError>{
 let limits=control.limits();crate::standards::v1::subsets::document::io::sqlite::snapshot::admit_layout(limits)?;
 let size=match payload{store::os_io::IoPayload::Binary(value)=>value.len(),store::os_io::IoPayload::Text(value)=>value.len()};if size>limits.max_file_bytes{return Err(ValueError::new(ValueRefusalKind::OwnershipLimit,"Semio Document native input exceeds file limit"))}
 control.allocation_stage(store::sqlite_snapshot::SqliteSnapshotPhase::DecodeNative,|remaining,checkpoint|{
  let mut callback=|event:semio_framework_value::native_decoding::NativeDecodeProgress|checkpoint(event.completed,event.total);let mut native_control=NativeDecodeControl::new(remaining,&mut callback);
  let result=(||->Result<SemioDocumentSnapshot,ValueError>{let result=match payload{
   store::os_io::IoPayload::Binary(value)=>{let body=store::semio_format::unwrap_binary_controlled(value,STDIO_SEMIODOCUMENT_DOCUMENT_SCHEMA,store::semio_format::Component::Pack,1,&mut native_control).map_err(store::semio_format::SemioError::into_value_error)?;binary(body,&mut native_control,limits)?},
   store::os_io::IoPayload::Text(value)=>{let body=store::semio_format::split_text_preamble_controlled(value,STDIO_SEMIODOCUMENT_DOCUMENT_SCHEMA,store::semio_format::Component::Dsl,1,&mut native_control).map_err(store::semio_format::SemioError::into_value_error)?;document(body,&mut native_control,limits)?}
  };let result=native::Owned::new(result);native_control.checkpoint()?;Ok(result.take())})();(result,native_control.owned_bytes())
 })?
}
fn f64(reader:&mut store::ByteReader<'_>)->Result<f64,ValueError>{reader.read_f64_le().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))}
fn boolean(value:u8)->Result<bool,ValueError>{match value{0=>Ok(false),1=>Ok(true),_=>Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Document native boolean"))}}
fn option<T>(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>,read:impl FnOnce(&mut store::ByteReader<'_>,&mut NativeDecodeControl<'_>)->Result<T,ValueError>)->Result<Option<T>,ValueError>{match reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?{0=>Ok(None),1=>read(reader,control).map(Some),_=>Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Document native optional presence"))}}
fn run_binary(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>)->Result<DocRun,ValueError>{let text=native::text(reader,control)?;let mut owner=native::Owned::new(DocRun{text,style:RunStyle{bold:false,italic:false,underline:false,size:None,font:None,color:None,link:None}});owner.get_mut().style.bold=boolean(reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?)?;owner.get_mut().style.italic=boolean(reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?)?;owner.get_mut().style.underline=boolean(reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?)?;owner.get_mut().style.size=option(reader,control,|reader,_|f64(reader))?;owner.get_mut().style.font=option(reader,control,native::text)?;owner.get_mut().style.color=option(reader,control,native::text)?;owner.get_mut().style.link=option(reader,control,native::text)?;Ok(owner.take())}
pub(crate) fn blocks_binary(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<Vec<DocBlock>,ValueError>{native::entities(entities,1,limits)?;native::binary_list(reader,control,limits,entities,|reader,control,entities|block_binary(reader,control,limits,entities))}
fn block_binary(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<DocBlock,ValueError>{control.scoped_depth(64,|control|{native::entities(entities,2,limits)?;Ok(match reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?{
0=>{let style_id=option(reader,control,native::text)?;let mut owner=native::Owned::new(DocBlock::Paragraph{style_id,runs:Vec::new()});if let DocBlock::Paragraph{runs:value,..}=owner.get_mut(){*value=native::binary_list(reader,control,limits,entities,|reader,control,_|run_binary(reader,control))?;}owner.take()},
1=>{let level=reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?;let style_id=option(reader,control,native::text)?;let mut owner=native::Owned::new(DocBlock::Heading{level,style_id,runs:Vec::new()});if let DocBlock::Heading{runs:value,..}=owner.get_mut(){*value=native::binary_list(reader,control,limits,entities,|reader,control,_|run_binary(reader,control))?;}owner.take()},
2=>{let ordered=boolean(reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?)?;let items=native::binary_list(reader,control,limits,entities,|reader,control,entities|Ok(DocListItem{blocks:blocks_binary(reader,control,limits,entities)?}))?;DocBlock::List{ordered,items}},
3=>{let rows=native::binary_list(reader,control,limits,entities,|reader,control,entities|{let cells=native::binary_list(reader,control,limits,entities,|reader,control,entities|Ok(DocTableCell{blocks:blocks_binary(reader,control,limits,entities)?}))?;Ok(DocTableRow{cells})})?;DocBlock::Table{rows}},
4=>{let language=option(reader,control,native::text)?;let mut owner=native::Owned::new(DocBlock::Code{language,text:String::new()});if let DocBlock::Code{text,..}=owner.get_mut(){*text=native::text(reader,control)?;}owner.take()},5=>DocBlock::Quote{blocks:blocks_binary(reader,control,limits,entities)?},
6=>{let image_id=native::text(reader,control)?;let mut owner=native::Owned::new(DocBlock::Image{image_id,alt:String::new(),width:None,height:None});if let DocBlock::Image{alt,width,height,..}=owner.get_mut(){*alt=native::text(reader,control)?;*width=option(reader,control,|reader,_|f64(reader))?;*height=option(reader,control,|reader,_|f64(reader))?;}owner.take()},7=>DocBlock::PageBreak,_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Document native block kind"))})})}
pub(crate) fn binary(body:&[u8],control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<SemioDocumentSnapshot,ValueError>{crate::standards::v1::subsets::document::io::sqlite::snapshot::admit_binary(body,control,limits)?;let mut reader=store::ByteReader::new(body);if reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?!=1{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"unsupported Document native format"))}let mut entities=0;native::entities(&mut entities,1,limits)?;let schema=native::text(&mut reader,control)?;let mut owner=native::Owned::new(SemioDocumentSnapshot{schema,styles:Vec::new(),images:Vec::new(),blocks:Vec::new()});owner.get_mut().styles=native::binary_list(&mut reader,control,limits,&mut entities,|reader,control,_|{let id=native::text(reader,control)?;let mut owner=native::Owned::new(DocStyle{id,name:String::new(),based_on:None});owner.get_mut().name=native::text(reader,control)?;owner.get_mut().based_on=option(reader,control,native::text)?;Ok(owner.take())})?;owner.get_mut().images=native::binary_list(&mut reader,control,limits,&mut entities,|reader,control,_|{let id=native::text(reader,control)?;let mut owner=native::Owned::new(DocImage{id,mime:String::new(),bytes:Vec::new()});owner.get_mut().mime=native::text(reader,control)?;owner.get_mut().bytes=control.copy_bytes(native::bytes(reader)?)?;Ok(owner.take())})?;owner.get_mut().blocks=blocks_binary(&mut reader,control,limits,&mut entities)?;if reader.remaining()!=0{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Document native trailing bytes"))}Ok(owner.take())}
fn bool_text(value:&str)->Result<bool,ValueError>{match value{"0"=>Ok(false),"1"=>Ok(true),_=>Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Document native boolean"))}}
fn optional_text<T>(value:&str,control:&mut NativeDecodeControl<'_>,read:impl FnOnce(&str,&mut NativeDecodeControl<'_>)->Result<T,ValueError>)->Result<Option<T>,ValueError>{if value=="[0]"{return Ok(None)}let[tag,value]=native::record(value,control)?;if tag!="1"{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Document native optional presence"))}read(value,control).map(Some)}
fn number_text(value:&str,control:&mut NativeDecodeControl<'_>)->Result<f64,ValueError>{control.scoped_stage(|control|{control.begin_stage(value.len())?;for _ in value.bytes(){control.step()?;}value.parse::<u64>().map(f64::from_bits).map_err(|_|ValueError::new(ValueRefusalKind::InvalidValue,"invalid Document native IEEE unsigned64 word"))})}
fn run_text(value:&str,control:&mut NativeDecodeControl<'_>)->Result<DocRun,ValueError>{let[text,style]=native::record(value,control)?;let[bold,italic,underline,size,font,color,link]=native::record(style,control)?;let text=native::hex_text(text,control)?;let mut owner=native::Owned::new(DocRun{text,style:RunStyle{bold:false,italic:false,underline:false,size:None,font:None,color:None,link:None}});owner.get_mut().style.bold=bool_text(bold)?;owner.get_mut().style.italic=bool_text(italic)?;owner.get_mut().style.underline=bool_text(underline)?;owner.get_mut().style.size=optional_text(size,control,number_text)?;owner.get_mut().style.font=optional_text(font,control,native::hex_text)?;owner.get_mut().style.color=optional_text(color,control,native::hex_text)?;owner.get_mut().style.link=optional_text(link,control,native::hex_text)?;Ok(owner.take())}
pub(crate) fn blocks_text(value:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<Vec<DocBlock>,ValueError>{native::entities(entities,1,limits)?;native::text_list(value,control,limits,entities,|value,control,entities|block_text(value,control,limits,entities))}
pub(crate) fn block_text(value:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<DocBlock,ValueError>{control.scoped_depth(64,|control|{native::entities(entities,2,limits)?;let(tag,value)=value.split_at_checked(1).ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"Document native block tag missing"))?;Ok(match tag{
"P"=>{let[style_id,runs]=native::record(value,control)?;let style_id=optional_text(style_id,control,native::hex_text)?;let mut owner=native::Owned::new(DocBlock::Paragraph{style_id,runs:Vec::new()});if let DocBlock::Paragraph{runs:value,..}=owner.get_mut(){*value=native::text_list(runs,control,limits,entities,|value,control,_|run_text(value,control))?;}owner.take()},
"H"=>{let[level,style_id,runs]=native::record(value,control)?;let level=control.scoped_stage(|control|{control.begin_stage(level.len())?;for _ in level.bytes(){control.step()?;}level.parse::<u8>().map_err(|_|ValueError::new(ValueRefusalKind::InvalidValue,"invalid Document native unsigned8 heading"))})?;let style_id=optional_text(style_id,control,native::hex_text)?;let mut owner=native::Owned::new(DocBlock::Heading{level,style_id,runs:Vec::new()});if let DocBlock::Heading{runs:value,..}=owner.get_mut(){*value=native::text_list(runs,control,limits,entities,|value,control,_|run_text(value,control))?;}owner.take()},
"L"=>{let[ordered,items]=native::record(value,control)?;let ordered=bool_text(ordered)?;let items=native::text_list(items,control,limits,entities,|value,control,entities|{let[blocks]=native::record(value,control)?;Ok(DocListItem{blocks:blocks_text(blocks,control,limits,entities)?})})?;DocBlock::List{ordered,items}},
"T"=>{let[rows]=native::record(value,control)?;let rows=native::text_list(rows,control,limits,entities,|value,control,entities|{let[cells]=native::record(value,control)?;let cells=native::text_list(cells,control,limits,entities,|value,control,entities|{let[blocks]=native::record(value,control)?;Ok(DocTableCell{blocks:blocks_text(blocks,control,limits,entities)?})})?;Ok(DocTableRow{cells})})?;DocBlock::Table{rows}},
"C"=>{let[language,text]=native::record(value,control)?;let language=optional_text(language,control,native::hex_text)?;let mut owner=native::Owned::new(DocBlock::Code{language,text:String::new()});if let DocBlock::Code{text:value,..}=owner.get_mut(){*value=native::hex_text(text,control)?;}owner.take()},
"Q"=>{let[blocks]=native::record(value,control)?;DocBlock::Quote{blocks:blocks_text(blocks,control,limits,entities)?}},
"I"=>{let[image_id,alt,width,height]=native::record(value,control)?;let image_id=native::hex_text(image_id,control)?;let mut owner=native::Owned::new(DocBlock::Image{image_id,alt:String::new(),width:None,height:None});if let DocBlock::Image{alt:value,width:w,height:h,..}=owner.get_mut(){*value=native::hex_text(alt,control)?;*w=optional_text(width,control,number_text)?;*h=optional_text(height,control,number_text)?;}owner.take()},"B"=>{let[]=native::record::<0>(value,control)?;DocBlock::PageBreak},_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Document native block kind"))})})}
pub(crate) fn document(body:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<SemioDocumentSnapshot,ValueError>{crate::standards::v1::subsets::document::io::sqlite::snapshot::admit_document(body,control,limits)?;let fields=native::fields(body,["schema","styles","images","blocks"],control)?;let mut entities=0;native::entities(&mut entities,1,limits)?;let schema=native::hex_text(fields[0].ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"Document native schema missing"))?,control)?;let mut owner=native::Owned::new(SemioDocumentSnapshot{schema,styles:Vec::new(),images:Vec::new(),blocks:Vec::new()});owner.get_mut().styles=native::text_list(fields[1].unwrap_or("[]"),control,limits,&mut entities,|value,control,_|{let[id,name,based_on]=native::record(value,control)?;let id=native::hex_text(id,control)?;let mut owner=native::Owned::new(DocStyle{id,name:String::new(),based_on:None});owner.get_mut().name=native::hex_text(name,control)?;owner.get_mut().based_on=optional_text(based_on,control,native::hex_text)?;Ok(owner.take())})?;owner.get_mut().images=native::text_list(fields[2].unwrap_or("[]"),control,limits,&mut entities,|value,control,_|{let[id,mime,bytes]=native::record(value,control)?;let id=native::hex_text(id,control)?;let mut owner=native::Owned::new(DocImage{id,mime:String::new(),bytes:Vec::new()});owner.get_mut().mime=native::hex_text(mime,control)?;owner.get_mut().bytes=native::hex(bytes,control)?;Ok(owner.take())})?;owner.get_mut().blocks=blocks_text(fields[3].unwrap_or("[]"),control,limits,&mut entities)?;Ok(owner.take())}
